import mongoose from"mongoose";const bannerSchema=new mongoose.Schema({title:{type:String,required:!0},subtitle:{type:String,required:!1},imageDesktop:{type:String,required:!0},imageMobile:{type:String,required:!1},linkUrl:{type:String,required:!0},active:{type:Boolean,default:!0},order:{type:Number,default:0},startDate:{type:Date,required:!1},endDate:{type:Date,required:!1},location:{type:String,default:"home_main",enum:["home_main","home_secondary","category_top"]},date:{type:Number,required:!0,default:Date.now()}}),bannerModel=mongoose.models.banner||mongoose.model("banner",bannerSchema);export default bannerModel;